	{
		StreamKind kind = StreamKind::Color;
		uint32_t width = 0;
		uint32_t height = 0;
		uint32_t dxgi_format = 0;      // DXGI_FORMAT value of the shared texture
		uint32_t source_resource_id = 0;
		float fps = 0.0f;
	};
}

